use egui_states::{Download, Signal, Static, Upload};

/// Describes a generated sample file; it comes with the server's offer.
#[egui_states::typed]
#[derive(Clone, Debug, Default, PartialEq)]
pub struct SampleInfo {
    pub mebibytes: u32,
    pub note: String,
}

#[derive(egui_states::State)]
pub struct TransferStates {
    /// The server sends a generated file here when asked.
    pub download: Download<SampleInfo>,
    /// The GUI sends generated bytes here; the server keeps them in memory.
    pub upload: Upload,
    /// Asks the server for a sample of this many MiB.
    pub request_download: Signal<u32>,
    /// What the server received last.
    pub upload_result: Static<String>,
}
